import { uniqueStrings } from './unique_base.mjs';

// Basic dedup preserving order
console.log(JSON.stringify(uniqueStrings(['a','b','a','c','b']))); // ['a','b','c']

// Case sensitivity
console.log(JSON.stringify(uniqueStrings(['a','A','a','A']))); // ['a','A']

// Whitespace not trimmed
console.log(JSON.stringify(uniqueStrings([' x','x',' x']))); // [' x','x']

// Input not mutated
const input = ['a','b','a'];
const out = uniqueStrings(input);
console.log(JSON.stringify(input)); // ['a','b','a']
console.log(input !== out); // true

// Empty array
console.log(JSON.stringify(uniqueStrings([]))); // []
"

